    client,
    brief,
    folioId,
    personas: custom && custom.length > 0 ? custom : DEFAULT_PERSONAS,
    enabled: roomSettings.backgroundRoom !== false,
    baselineText: paragraphTextFromHtml(seed ?? ""),
