311	  // Key the cache on the voice that will actually be used, so two editors
312	  // sharing a fallback name never collide on one clip.
313	  const settings = await getCachedAiSettings();
314	  const resolved = resolveFeatureConfig(settings, "voice-narration");
315	  const override = settings.perFeature["voice-narration"];
316	  const voice = resolveVoice(spoken, settings) ?? spoken.voice ?? "alloy";
317	  const provider = resolved?.provider.id ?? "hosted";
318	  const model = resolved?.model ?? "hosted";
319	  const key = cacheKey(
320	    text,
321	    provider,
322	    model,
323	    voice,
324	    override?.responseFormat ?? "mp3",
325	    override?.speed,
326	    spoken.instructions ?? override?.instructions,
327	  );
328	
329	  setState("loading", req.id);
330	
331	  try {
332	    let url = cache.get(key);
333	    if (!url) {
334	      const result = await synthesize({ ...spoken, text });
335	      if (mine !== generation) return; // the writer moved on
336	      url = URL.createObjectURL(result.audio);
337	      remember(key, url);
338	    }
339	    if (mine !== generation) return;
340	
341	    audio = audio ?? new Audio();
342	    audio.src = url;
343	    audio.onended = () => {
344	      if (mine === generation) setState("idle", null);
345	    };
346	    audio.onerror = () => {
347	      if (mine !== generation) return;
348	      setState(
349	        "error",
350	        req.id,
351	        createAppError("PROVIDER_ERROR", {
352	          source: "provider",
353	          metadata: { feature: "voice-narration", operation: "playback" },
354	        }),
355	      );
356	    };
357	    await audio.play();
358	    if (mine === generation) setState("playing", req.id);
359	  } catch (err) {
360	    if (mine !== generation) return;
361	    setState(
362	      "error",
363	      req.id,
364	      normalizeApplicationError(err, {
365	        source: "provider",
366	        metadata: { feature: "voice-narration", operation: "synthesize" },
367	      }),
368	    );
369	  }
370	}
