/* ── The composer ─────────────────────────────────────────────────
   One surface that holds the text, the microphone and the send key,
   the way every modern chat client does it. The previous arrangement
   stacked three separate controls down the page, which read as three
   unrelated widgets rather than one place to speak from.

   The whole card takes the focus treatment, not the textarea alone —
   the writer is focusing "the composer", and a ring drawn around only
   the inner box makes the toolbar look detached from it. */
.composer {
  display: flex;
  flex-direction: column;
  background: var(--color-paper-soft);
  border: 1px solid var(--color-paper-3);
  border-radius: 3px;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
  box-shadow: 0 1px 2px rgba(31, 27, 22, 0.04);
}
.composer:focus-within {
  border-color: var(--color-vermilion);
  box-shadow:
    0 0 0 3px rgba(193, 39, 45, 0.12),
    0 2px 10px -6px rgba(31, 27, 22, 0.35);
}
.composer[data-recording="true"] {
  border-color: var(--color-vermilion);
}
.composer[data-disabled="true"] {
  opacity: 0.6;
}

/* Borderless because the card around it already is the border. */
.composer-input {
  width: 100%;
  resize: none;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  line-height: 1.55;
  padding: 0.7rem 0.85rem 0.15rem;
  max-height: 40vh;
  overflow-y: auto;
}
.composer-input::placeholder {
  color: var(--color-ink-muted);
}
.composer-input:disabled {
  cursor: not-allowed;
}

.composer-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.5rem 0.45rem;
}
.composer-bar-left {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  flex: 1;
}

/* The send key. Square-ish rather than a pill: this is a press, not a
   chat bubble, and a 2px radius is the house rule everywhere else. */
.composer-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 1.85rem;
  width: 1.85rem;
  flex-shrink: 0;
  border-radius: 2px;
  border: 1px solid var(--color-ink);
  background: var(--color-ink);
  color: var(--color-paper);
  cursor: pointer;
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.18s ease;
}
.composer-send:hover:not(:disabled) {
  background: var(--color-vermilion-2);
  border-color: var(--color-vermilion-2);
  box-shadow: 0 4px 14px -8px rgba(156, 26, 31, 0.6);
}
.composer-send:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
  box-shadow: none;
}
.composer-send:disabled {
  background: transparent;
  border-color: var(--color-paper-3);
  color: var(--color-ink-muted);
  cursor: not-allowed;
  box-shadow: none;
}

/* The keyboard hint sits next to the send key and disappears on narrow
   screens, where there is no keyboard to hint about. */
.composer-hint {
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
  white-space: nowrap;
}
@media (max-width: 640px) {
  .composer-hint {
    display: none;
  }
}

/* Recording and transcribing both live in the toolbar rather than
   replacing the composer, so the draft the writer already typed never
   disappears behind the recorder. */
.composer-recording {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}
.composer-rec-dot {
  height: 0.45rem;
  width: 0.45rem;
  flex-shrink: 0;
  border-radius: 9999px;
  background: var(--color-vermilion);
  animation: composer-pulse 1.2s ease-in-out infinite;
}
@keyframes composer-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
.composer-elapsed {
  font-family: var(--font-typewriter);
  font-size: 0.7rem;
  font-variant-numeric: tabular-nums;
  color: var(--color-ink);
}

@media (prefers-reduced-motion: reduce) {
  .composer-rec-dot {
    animation: none;
  }
  .composer-send:active:not(:disabled) {
    transform: none;
  }
}
