/* ── The ruler ────────────────────────────────────────────────────
   Word's page ruler, in Twyne's ink. It sits directly above the page
   and spans exactly the page's width, so the markers line up with the
   real margins rather than approximating them. Dragging a marker is
   the natural way to change a margin: you move the edge of the text,
   and the text reflows under your hand.

   The shaded ends are the margins; the pale middle is the live text
   column, which is the same relationship Word draws. */
.ruler {
  position: relative;
  height: 1.35rem;
  margin: 0 auto 0.25rem;
  user-select: none;
  font-family: var(--font-typewriter);
  touch-action: none;
}
.ruler-track {
  position: absolute;
  inset: 0.3rem 0 0.3rem;
  background: var(--color-paper-3);
  border-radius: 1px;
}
.ruler-column {
  position: absolute;
  top: 0.3rem;
  bottom: 0.3rem;
  background: var(--color-paper-soft);
  border-left: 1px solid var(--color-ink-muted);
  border-right: 1px solid var(--color-ink-muted);
}
.ruler-tick {
  position: absolute;
  top: 50%;
  width: 1px;
  height: 0.3rem;
  transform: translateY(-50%);
  background: var(--color-ink-muted);
  opacity: 0.5;
}

/* Generous hit area around a deliberately small visual marker: the
   marker must not cover the text it is aligned with, but a 3px drag
   target is unusable. */
.ruler-handle {
