/* ── Lists in the manuscript ──────────────────────────────────────
   Tailwind's preflight strips markers and padding from every ul/ol,
   which left bullet and numbered lists in the editor rendering as
   bare paragraphs — the writer pressed "list" and nothing visibly
   happened. These rules restore them for the manuscript only, so the
   reset still holds for the application chrome around it.

   Markers cycle by depth the way a word processor's do, so nesting
   reads as structure rather than as an accident of indentation. */
.twyne-editor .ProseMirror ul,
.twyne-editor .ProseMirror ol {
  padding-left: 1.6em;
  margin: 0 0 1.1rem;
}
.twyne-editor .ProseMirror ul {
  list-style: disc outside;
}
.twyne-editor .ProseMirror ul ul {
  list-style-type: circle;
}
.twyne-editor .ProseMirror ul ul ul {
  list-style-type: square;
}
.twyne-editor .ProseMirror ol {
  list-style: decimal outside;
}
.twyne-editor .ProseMirror ol ol {
  list-style-type: lower-alpha;
}
.twyne-editor .ProseMirror ol ol ol {
  list-style-type: lower-roman;
}

/* Nested lists tuck under their parent rather than opening a gap. */
.twyne-editor .ProseMirror li > ul,
.twyne-editor .ProseMirror li > ol {
  margin: 0.25rem 0 0.25rem;
}
.twyne-editor .ProseMirror li {
  margin: 0.2rem 0;
  padding-left: 0.15em;
}
/* A list item's paragraph is a layout wrapper, not a new block of
   prose — the paragraph's own bottom margin would double-space the
   list. */
.twyne-editor .ProseMirror li > p {
  margin: 0;
}
.twyne-editor .ProseMirror li::marker {
  color: var(--color-ink-muted);
}
.twyne-editor .ProseMirror ol > li::marker {
  font-family: var(--font-typewriter);
  font-size: 0.85em;
}

/* The task list opts out of markers entirely; it draws checkboxes. */
.twyne-editor .ProseMirror ul[data-type="taskList"],
.twyne-editor .ProseMirror ul.twyne-task-list {
  list-style: none;
}

/* Indented blocks keep their left margin in the exported document
   too, since the indent is written as an inline style on the node. */
